import React from "react";
import { CheckCircle } from "lucide-react";

const CryptoFlow = ({ currentStep = 0, mode = "hybrid" }) => {

  // ================= HYBRID =================
  const hybridSteps = [
    {
      label: "Ephemeral Agreement",
      sub: "X25519",
      details: ["Generate ephemeral key", "Exchange public values"]
    },
    {
      label: "Encapsulate Secret",
      sub: "Kyber",
      details: ["Compute shared secret", "Create ciphertext"]
    },
    {
      label: "HKDF Derivation",
      sub: "SHA-256",
      details: ["Mix salt", "Expand key"]
    },
    {
      label: "Encrypt Payload",
      sub: "AES-GCM",
      details: ["Encrypt blocks", "Generate tag"]
    },
    {
      label: "Upload to Cloud",
      sub: "Untrusted",
      details: ["Pack blob", "Push storage"]
    }
  ];

  // ================= RSA =================
  const rsaSteps = [
    {
      label: "Generate Keypair",
      sub: "RSA-2048",
      details: ["Public key", "Private key"]
    },
    {
      label: "Apply Padding",
      sub: "OAEP",
      details: ["Prepare message"]
    },
    {
      label: "RSA Encrypt",
      sub: "Mod Exp",
      details: ["Cipher output"]
    },
    {
      label: "Build Blob",
      sub: "Metadata",
      details: ["Attach headers"]
    },
    {
      label: "Upload to Cloud",
      sub: "Untrusted",
      details: ["Push storage"]
    }
  ];

  const steps = mode === "hybrid" ? hybridSteps : rsaSteps;

  // ================= COLORS =================
  const nodeColor =
    mode === "hybrid" ? "border-neon-green text-neon-green" : "border-purple-400 text-purple-400";

  const detailColor =
    mode === "hybrid" ? "text-neon-green" : "text-purple-300";

  const lineColor =
    mode === "hybrid" ? "bg-neon-green" : "bg-purple-400";

  return (
    <div className="bg-black/40 p-8 rounded-xl border border-scifi-border">

      {/* MAIN FLOW */}
      <div className="flex justify-between relative">

        {/* MAIN PROGRESS LINE */}
        <div className="absolute top-6 left-0 w-full h-[2px] bg-gray-800"></div>

        <div
          className={`absolute top-6 left-0 h-[2px] transition-all ${lineColor}`}
          style={{
            width: `${(Math.max(currentStep - 1, 0) / (steps.length - 1)) * 100}%`
          }}
        />

        {steps.map((step, i) => {
          const active = currentStep >= i + 1;

          return (
            <div key={i} className="relative z-10 flex flex-col items-center w-44">

              {/* PARENT NODE */}
              <div
                className={`w-12 h-12 rounded-full border-2 bg-black flex items-center justify-center
                ${active ? nodeColor : "border-gray-700 text-gray-700"}`}
              >
                {active ? <CheckCircle size={18} /> : <div className="w-2 h-2 bg-gray-600 rounded-full"/>}
              </div>

              {/* LABEL */}
              <div className="text-center mt-3">
                <p className={`text-[11px] font-bold ${active ? "text-white" : "text-gray-600"}`}>
                  {step.label}
                </p>
                <p className="text-[10px] text-gray-500 font-mono">{step.sub}</p>
              </div>

              {/* BRANCH LINE DOWN */}
              <div className={`w-[2px] h-6 mt-2 ${active ? lineColor : "bg-gray-800"}`} />

              {/* CHILDREN */}
              <div className="flex gap-3 mt-2">
                {step.details.map((d, idx) => (
                  <div key={idx} className="flex flex-col items-center">

                    {/* line */}
                    <div className={`w-[2px] h-4 ${active ? lineColor : "bg-gray-800"}`} />

                    {/* child node */}
                    <div className={`w-6 h-6 rounded-full border ${active ? nodeColor : "border-gray-700"}`} />

                    {/* text */}
                    <p className={`mt-2 text-[10px] font-mono ${detailColor}`}>
                      {d}
                    </p>

                  </div>
                ))}
              </div>

            </div>
          );
        })}
      </div>
    </div>
  );
};

export default CryptoFlow;
